private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (i < 0) {
        throw new IllegalArgumentException("Index cannot be negative");
    }
    int limit = bb.limit();
    if (i >= limit) {
        return i;
    }
    try {
        int pos = i;
        int b0 = bb.get(pos) & 0xFF;
        int seqLen;
        int codePoint;
        if ((b0 & 0x80) == 0) {
            seqLen = 1;
            codePoint = b0;
        } else if ((b0 & 0xE0) == 0xC0) {
            seqLen = 2;
            if (pos + 1 >= limit) {
                codePoint = 0xFFFD;
            } else {
                int b1 = bb.get(pos + 1) & 0xFF;
                if ((b1 & 0xC0) != 0x80) {
                    codePoint = 0xFFFD;
                } else {
                    int part1 = b0 & 0x1F;
                    int part2 = b1 & 0x3F;
                    codePoint = (part1 << 6) | part2;
                    if (codePoint < 0x80) {
                        codePoint = 0xFFFD;
                    }
                }
            }
        } else if ((b0 & 0xF0) == 0xE0) {
            seqLen = 3;
            if (pos + 2 >= limit) {
                codePoint = 0xFFFD;
            } else {
                int b1 = bb.get(pos + 1) & 0xFF;
                int b2 = bb.get(pos + 2) & 0xFF;
                if ((b1 & 0xC0) != 0x80 || (b2 & 0xC0) != 0x80) {
                    codePoint = 0xFFFD;
                } else {
                    int part1 = b0 & 0x0F;
                    int part2 = b1 & 0x3F;
                    int part3 = b2 & 0x3F;
                    codePoint = (part1 << 12) | (part2 << 6) | part3;
                    if (codePoint < 0x800 || (codePoint >= 0xD800 && codePoint <= 0xDFFF)) {
                        codePoint = 0xFFFD;
                    }
                }
            }
        } else if ((b0 & 0xF8) == 0xF0) {
            seqLen = 4;
            if (pos + 3 >= limit) {
                codePoint = 0xFFFD;
            } else {
                int b1 = bb.get(pos + 1) & 0xFF;
                int b2 = bb.get(pos + 2) & 0xFF;
                int b3 = bb.get(pos + 3) & 0xFF;
                if ((b1 & 0xC0) != 0x80 || (b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) {
                    codePoint = 0xFFFD;
                } else {
                    int part1 = b0 & 0x07;
                    int part2 = b1 & 0x3F;
                    int part3 = b2 & 0x3F;
                    int part4 = b3 & 0x3F;
                    codePoint = (part1 << 18) | (part2 << 12) | (part3 << 6) | part4;
                    if (codePoint < 0x10000 || codePoint > 0x10FFFF) {
                        codePoint = 0xFFFD;
                    }
                }
            }
        } else {
            seqLen = 1;
            codePoint = 0xFFFD;
        }
        if (codePoint <= 0xFFFF) {
            sb.append((char) codePoint);
        } else {
            codePoint -= 0x10000;
            char high = (char) ((codePoint >> 10) + 0xD800);
            char low = (char) ((codePoint & 0x3FF) + 0xDC00);
            sb.append(high).append(low);
        }
        return pos + seqLen;
    } catch (Exception e) {
        return i;
    }
}

