public static int nullSafeHashCode(long[] array){
    if (array == null) {
        return 0;
    }
    int result = 1;
    for (long value : array) {
        int elementHash = (int)(value ^ (value >>> 32));
        result = 31 * result + elementHash;
    }
    return result;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null || node.left == null) {
        return node;
    }
    TreeNode<T> left = node.left;
    node.left = left.right;
    left.right = node;
    return left;
}

public static void addToClassPath(Vector<URL> cpV, String dir) {
    if (cpV == null) {
        throw new IllegalArgumentException("Classpath vector cannot be null");
    }
    if (dir == null || dir.isEmpty()) {
        throw new IllegalArgumentException("Directory path cannot be null or empty");
    }
    File dirFile = new File(dir);
    if (!dirFile.exists() || !dirFile.isDirectory()) {
        throw new IllegalArgumentException("Directory does not exist or is not a directory: " + dir);
    }
    File[] files = dirFile.listFiles();
    if (files == null) {
        return;
    }
    for (File f : files) {
        if (f.isFile() && f.getName().toLowerCase().endsWith(".jar")) {
            try {
                URL url = f.toURI().toURL();
                if (!cpV.contains(url)) {
                    cpV.add(url);
                }
            } catch (MalformedURLException e) {
                throw new RuntimeException("Failed to convert file to URL: " + f, e);
            }
        }
    }
}

