public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }
    IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<>(graph, graph);
    for (V v : graph.vertexSet()) {
        mapping.addMapping(v, v);
    }
    for (E e : graph.edgeSet()) {
        mapping.addMapping(e, e);
    }
    return mapping;
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    if (!file.exists()) {
        throw new IOException("File does not exist: " + file);
    }
    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children == null) {
            throw new IOException("Unable to list contents of directory: " + file);
        }
        for (File child : children) {
            forceDeleteOnExit(child);
        }
    }
    file.deleteOnExit();
}

