public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType) || targetType == null) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Map<TypeVariable<?>, Type> typeVarMap = new HashMap<>();
    buildTypeVariableMap(targetType, typeVarMap);
    Type[] args = pt.getActualTypeArguments();
    Class<?>[] result = new Class<?>[args.length];
    for (int i = 0; i < args.length; i++) {
        Type resolved = resolveType(args[i], typeVarMap);
        if (resolved instanceof Class<?>) {
            result[i] = (Class<?>) resolved;
        } else {
            return null;
        }
    }
    return result;
}

private static void buildTypeVariableMap(Class<?> clazz, Map<TypeVariable<?>, Type> map) {
    if (clazz == null || clazz == Object.class) {
        return;
    }
    Type genericSuper = clazz.getGenericSuperclass();
    processType(genericSuper, map);
    for (Type iface : clazz.getGenericInterfaces()) {
        processType(iface, map);
    }
}

private static void processType(Type type, Map<TypeVariable<?>, Type> map) {
    if (type instanceof ParameterizedType) {
        ParameterizedType pt = (ParameterizedType) type;
        Class<?> raw = (Class<?>) pt.getRawType();
        TypeVariable<?>[] vars = raw.getTypeParameters();
        Type[] args = pt.getActualTypeArguments();
        for (int i = 0; i < vars.length; i++) {
            Type arg = args[i];
            Type resolvedArg = resolveType(arg, map);
            map.put(vars[i], resolvedArg);
        }
        buildTypeVariableMap(raw, map);
    } else if (type instanceof Class<?>) {
        // No type parameters to map
    }
}

private static Type resolveType(Type type, Map<TypeVariable<?>, Type> map) {
    if (type instanceof TypeVariable<?>) {
        Type resolved = map.get(type);
        if (resolved == null) {
            return type;
        }
        if (resolved instanceof TypeVariable<?>) {
            return resolveType(resolved, map);
        }
        return resolved;
    } else if (type instanceof ParameterizedType) {
        return ((ParameterizedType) type).getRawType();
    } else {
        return type;
    }
}

@Override public void accept(final METRICS data){
    if (data == null) {
