    }
    // Assume a field named 'cache' of type Map<METRICS, METRICS> exists in the enclosing class.
    if (cache == null) {
        throw new IllegalStateException("Cache not initialized");
    }
    METRICS existing = cache.get(data);
    if (existing != null) {
        try {
            // Merge the new data into the existing value.  The METRICS type is expected to provide a merge method.
            existing.merge(data);
        } catch (Exception e) {
            // If merge fails, fall back to replacing the entry.
            cache.put(data, data);
        }
    } else {
        cache.put(data, data);
    }
}

