static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        return timeBucket;
    }
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;
    long newDay = day - ((day - 1) % dayStep);
    return year * 10000 + month * 100 + newDay;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null || index < 0 || len <= 0) {
        return 0;
    }
    int end = index + len;
    if (end > str.length()) {
        end = str.length();
    }
    int size = 0;
    for (int i = index; i < end; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
            size += 4;
            i++; // skip low surrogate
        } else {
            size += 3;
        }
    }
    return size;
}

