public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        return lb;
    }
    try {
        // Prefer using the session's UTF‑8 writer if available
        session.writeUTF8(str, lb);
    } catch (Exception e) {
        // Fallback: manually encode to UTF‑8 and write to the buffer
        try {
            byte[] bytes = str.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);
            // Assume LinkedBuffer has a write(byte[], int, int) method
            lb.write(bytes, 0, bytes.length);
        } catch (Exception ex) {
            // If even this fails, silently ignore – the caller can decide what to do
        }
    }
    return lb;
}

