        prevTarget.nextTarget = nextTarget;
    } else if (nextTarget != null) {
        nextTarget.prevTarget = null;
    }
    if (nextTarget != null) {
        nextTarget.prevTarget = prevTarget;
    }

    // Nullify this edge's pointers
    prev = null;
    next = null;
    prevTarget = null;
    nextTarget = null;
}

