public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    // Ignore leading '/' for absolute paths
    int start = rawPath.startsWith("/") ? 1 : 0;
    String path = rawPath.substring(start);
    String[] parts = path.split("/", -1); // keep trailing empty segments
    for (String part : parts) {
        String decoded = part;
        if (decode) {
            try {
                decoded = URLDecoder.decode(part, StandardCharsets.UTF_8.name());
            } catch (UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        segments.add(new PathSegmentImpl(part, decoded));
    }
    return segments;
}

