private void putAbstractTypes(final int start, final int end) {
    if (currentFrame == null) {
        throw new IllegalStateException("currentFrame is null");
    }
    if (stackMapTableEntries == null) {
        throw new IllegalStateException("stackMapTableEntries is null");
    }
    if (start < 0 || end > currentFrame.length || start > end) {
        throw new IllegalArgumentException("Invalid start or end indices");
    }
    for (int i = start; i < end; i++) {
        AbstractType type = currentFrame[i];
        if (type == null) {
            throw new IllegalStateException("AbstractType at index " + i + " is null");
        }
        int tag = type.getTag();
        stackMapTableEntries.putByte(tag);
        switch (tag) {
            case 7: // Object
                String internalName = type.getType().getInternalName();
                if (internalName == null) {
                    throw new IllegalStateException("Object type internal name is null at index " + i);
                }
                int cpIndex = getConstantPoolIndex(internalName);
                if (cpIndex <= 0) {
                    throw new IllegalStateException("Invalid constant pool index for " + internalName);
                }
                stackMapTableEntries.putShort(cpIndex);
                break;
            case 8: // Uninitialized
                int offset = type.getOffset();
                if (offset < 0) {
                    throw new IllegalStateException("Invalid uninitialized offset at index " + i);
                }
                stackMapTableEntries.putShort(offset);
                break;
            default:
                // No additional data for other tags
                break;
        }
    }
}

