public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = str.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '\"':
                    sb.append('\"');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case 'u':
                    // Unicode escape: \uXXXX
                    if (i + 5 < len) {
                        String hex = str.substring(i + 2, i + 6);
                        try {
                            int code = Integer.parseInt(hex, 16);
                            sb.append((char) code);
                            i += 5;
                        } catch (NumberFormatException e) {
                            // Invalid hex, treat literally
                            sb.append('\\').append('u');
                            i++;
                        }
                    } else {
                        // Not enough characters, treat literally
                        sb.append('\\').append('u');
                        i++;
                    }
                    break;
                default:
                    if (next >= '0' && next <= '7') {
                        // Octal escape: up to three octal digits
                        int j = i + 1;
                        int val = 0;
                        int count = 0;
                        while (j < len && count < 3) {
                            char d = str.charAt(j);
                            if (d >= '0' && d <= '7') {
                                val = val * 8 + (d - '0');
                                j++;
                                count++;
                            } else {
                                break;
                            }
                        }
                        sb.append((char) val);
                        i = j - 1;
                    } else {
                        // Unrecognized escape, keep as is
                        sb.append(next);
                        i++;
                    }
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

