final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    if (constantPoolEntryIndex <= 0) {
        throw new IllegalArgumentException("constantPoolEntryIndex must be > 0");
    }
    int offset = getConstantPoolEntryOffset(constantPoolEntryIndex);
    if (offset < 0) {
        throw new IllegalArgumentException("Invalid constant pool index");
    }
    // CONSTANT_Utf8 tag is 1
    int tag = classFileBuffer[offset] & 0xFF;
    if (tag != 1) {
        throw new IllegalArgumentException("Entry at index " + constantPoolEntryIndex + " is not a CONSTANT_Utf8");
    }
    int length = ((classFileBuffer[offset + 1] & 0xFF) << 8) | (classFileBuffer[offset + 2] & 0xFF);
    if (charBuffer.length < length) {
        throw new IllegalArgumentException("charBuffer too small for UTF8 string of length " + length);
    }
    String s = new String(classFileBuffer, offset + 3, length, java.nio.charset.StandardCharsets.UTF_8);
    int strLen = s.length();
    if (charBuffer.length < strLen) {
        throw new IllegalArgumentException("charBuffer too small for decoded string length " + strLen);
    }
    s.getChars(0, strLen, charBuffer, 0);
    return s;
}

private static char decodeHexNibble(final char c) {
    if ('0' <= c && c <= '9') {
        return (char) (c - '0');
    } else if ('a' <= c && c <= 'f') {
        return (char) (c - 'a' + 10);
    } else if ('A' <= c && c <= 'F') {
        return (char) (c - 'A' + 10);
    } else {
        return Character.MAX_VALUE;
    }
}

