    if (charsToDelete == null || charsToDelete.isEmpty()) {
        return inString;
    }
    // Build a lookup table for characters to delete
    boolean[] deleteTable = new boolean[Character.MAX_VALUE + 1];
    for (int i = 0; i < charsToDelete.length(); i++) {
        deleteTable[charsToDelete.charAt(i)] = true;
    }
    StringBuilder sb = new StringBuilder(inString.length());
    for (int i = 0; i < inString.length(); i++) {
        char c = inString.charAt(i);
        if (!deleteTable[c]) {
            sb.append(c);
        }
    }
    return sb.toString();
}

