public int compare(Object aObj1, Object aObj2) {
    // Handle nulls: null is considered less than any non-null value
    if (aObj1 == aObj2) {
        return 0; // covers both null
    }
    if (aObj1 == null) {
        return -1;
    }
    if (aObj2 == null) {
        return 1;
    }

    // Attempt to use Comparable if both objects implement it
    if (aObj1 instanceof Comparable && aObj2 instanceof Comparable) {
        try {
            @SuppressWarnings("unchecked")
            Comparable<Object> c1 = (Comparable<Object>) aObj1;
            return c1.compareTo(aObj2);
        } catch (ClassCastException | Exception e) {
            // Fall back to other comparison strategies
        }
    }

    // Fallback: compare by class name
    String className1 = aObj1.getClass().getName();
    String className2 = aObj2.getClass().getName();
    int cmp = className1.compareTo(className2);
    if (cmp != 0) {
        return cmp;
    }

    // If same class, compare by string representation
    String s1 = aObj1.toString();
    String s2 = aObj2.toString();
    return s1.compareTo(s2);
}

