protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return null;
    }
    // Build adjacency map
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        if (e == null) {
            throw new IllegalArgumentException("Edge set contains null edge");
        }
        if (!graph.containsEdge(e)) {
            throw new IllegalArgumentException("Edge not in graph: " + e);
        }
        V source = graph.getEdgeSource(e);
        V target = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(source, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(target, k -> new ArrayList<>()).add(e);
    }
    // Validate that each vertex has degree 2
    for (Map.Entry<V, List<E>> entry : adjacency.entrySet()) {
        if (entry.getValue().size() != 2) {
            throw new IllegalArgumentException("Vertex " + entry.getKey() + " does not have degree 2");
        }
    }
    // Start traversal from an arbitrary vertex
    V start = adjacency.keySet().iterator().next();
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    double weight = 0.0;
    V current = start;
    E prevEdge = null;
    vertexList.add(current);
    int steps = 0;
    while (steps < tour.size()) {
        List<E> edges = adjacency.get(current);
        E nextEdge = null;
        for (E e : edges) {
            if (!e.equals(prevEdge)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) {
            throw new IllegalArgumentException("Cannot find next edge from vertex " + current);
        }
        edgeList.add(nextEdge);
        weight += graph.getEdgeWeight(nextEdge);
        V nextVertex = graph.getEdgeSource(nextEdge).equals(current) ? graph.getEdgeTarget(nextEdge) : graph.getEdgeSource(nextEdge);
        current = nextVertex;
        vertexList.add(current);
        prevEdge = nextEdge;
        steps++;
    }
    // Ensure the tour is closed
    if (!current.equals(start)) {
        throw new IllegalArgumentException("Edge set does not form a closed tour");
    }
    return new org.jgrapht.graph.DefaultGraphPath<>(graph, vertexList, edgeList, weight);
}

