public boolean isCompatible(DataTable dataset){
    if (dataset == null) {
        return false;
    }
    try {
        // Attempt to retrieve the bucket from both objects.
        // If the bucket is stored in a field named 'bucket', use that; otherwise, try a getter.
        Object thisBucket = null;
        Object otherBucket = null;

        // Try to get bucket via getter if available
        try {
            thisBucket = this.getClass().getMethod("getBucket").invoke(this);
        } catch (NoSuchMethodException ignored) {
            // Fallback to direct field access
            try {
                thisBucket = this.getClass().getDeclaredField("bucket").get(this);
            } catch (Exception ignored2) {
                // If still not found, leave as null
            }
        }

        try {
            otherBucket = dataset.getClass().getMethod("getBucket").invoke(dataset);
        } catch (NoSuchMethodException ignored) {
            try {
                otherBucket = dataset.getClass().getDeclaredField("bucket").get(dataset);
            } catch (Exception ignored2) {
            }
        }

        // If both buckets are null, they are considered compatible
        if (thisBucket == null && otherBucket == null) {
            return true;
        }

        // If one is null and the other is not, they are not compatible
        if (thisBucket == null || otherBucket == null) {
            return false;
        }

        // Compare the bucket values
        return thisBucket.equals(otherBucket);
    } catch (Exception e) {
        // Any exception during reflection or comparison results in incompatibility
        return false;
    }
}

