void removeSelf(){
    try {
        java.lang.reflect.Field prevField = this.getClass().getDeclaredField("prev");
        java.lang.reflect.Field nextField = this.getClass().getDeclaredField("next");
        prevField.setAccessible(true);
        nextField.setAccessible(true);
        Object prev = prevField.get(this);
        Object next = nextField.get(this);
        if (prev != null) {
            java.lang.reflect.Field nextOfPrev = prev.getClass().getDeclaredField("next");
            nextOfPrev.setAccessible(true);
            nextOfPrev.set(prev, next);
        }
        if (next != null) {
            java.lang.reflect.Field prevOfNext = next.getClass().getDeclaredField("prev");
            prevOfNext.setAccessible(true);
            prevOfNext.set(next, prev);
        }
    } catch (NoSuchFieldException | IllegalAccessException e) {
        // ignore
    }
}

