    }
    if (from < 0 || to >= arr.length || from > to) {
        throw new IllegalArgumentException("Invalid range: from=" + from + ", to=" + to);
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new NullPointerException("list");
    }
    if (list == this || list.isEmpty()) {
        return;
    }
    // Iterate over the source list's nodes, removing each from the source
    // and adding it to this list.  We capture the next node before
    // removal to avoid losing the traversal reference.
    ListNode<E> node = list.getFirst();
    while (node != null) {
        ListNode<E> next = node.getNext();
        // Remove from the source list
        list.removeListNode(node);
        // Add to this list
        this.addListNode(node);
        node = next;
    }
}

