private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    for (V v1 : vertices) {
        if (v1 == null) {
            return false;
        }
        for (V v2 : vertices) {
            if (v1 == v2) {
                continue;
            }
            if (v2 == null) {
                return false;
            }
            if (graph.getEdge(v1, v2) == null) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new java.util.ArrayList<>();
    if (keys == null) return result;
    for (K key : keys){
        if (!(key instanceof Integer)){
            result.add(null);
            continue;
        }
        Integer k = (Integer) key;
        Integer maxLower = null;
        for (K other : keys){
            if (!(other instanceof Integer)) continue;
            Integer o = (Integer) other;
            if (o < k){
                if (maxLower == null || o > maxLower){
                    maxLower = o;
                }
            }
        }
        result.add(maxLower);
    }
    return result;
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("descriptor cannot be null");
    }
    int len = descriptor.length();
    if (len == 0) {
        return;
    }
    // If method descriptor
    if (descriptor.charAt(0) == '(') {
        int end = descriptor.indexOf(')');
        if (end == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        int i = 1;
        while (i < end) {
            char c = descriptor.charAt(i);
            if (c == 'L') {
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Invalid object type descriptor");
                }
                pos--;
                i = semicolon + 1;
            } else if (c == '[') {
                // skip all '['
                while (i < end && descriptor.charAt(i) == '[') {
                    i++;
                }
                if (i >= end) {
                    throw new IllegalArgumentException("Invalid array type descriptor");
                }
                // component type
                if (descriptor.charAt(i) == 'L') {
                    int semicolon = descriptor.indexOf(';', i);
                    if (semicolon == -1) {
                        throw new IllegalArgumentException("Invalid array type descriptor");
                    }
                    i = semicolon + 1;
                } else {
                    i++;
                }
                pos--;
            } else {
                // primitive
                if (c == 'J' || c == 'D') {
                    pos -= 2;
                } else {
                    pos--;
                }
                i++;
            }
            if (pos < 0) {
                throw new IllegalStateException("Stack underflow");
            }
        }
    } else {
        // type descriptor
        char c = descriptor.charAt(0);
        if (c == 'L') {
            int semicolon = descriptor.indexOf(';', 0);
            if (semicolon == -1) {
                throw new IllegalArgumentException("Invalid object type descriptor");
            }
            pos--;
        } else if (c == '[') {
            int i = 0;
            while (i < len && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i >= len) {
                throw new IllegalArgumentException("Invalid array type descriptor");
            }
            if (descriptor.charAt(i) == 'L') {
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Invalid array type descriptor");
                }
                i = semicolon + 1;
            } else {
                i++;
            }
            pos--;
        } else {
            if (c == 'J' || c == 'D') {
                pos -= 2;
            } else {
                pos--;
            }
        }
        if (pos < 0) {
            throw new IllegalStateException("Stack underflow");
        }
    }
}

private List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> bounds = new java.util.ArrayList<>();
    if (keys == null) {
        return bounds;
    }
    for (K key : keys) {
        if (key == null) {
            bounds.add(0);
            continue;
        }
        int bound = Math.abs(key.hashCode());
        bounds.add(bound);
    }
    return bounds;
}

