public static String applyRelativePath(String path, String relativePath) {
    if (path == null) path = "";
    if (relativePath == null) return path;
    boolean leadingSlash = path.startsWith("/");
    String[] pathParts = path.split("/");
    java.util.ArrayList<String> stack = new java.util.ArrayList<>();
    for (String part : pathParts) {
        if (part.isEmpty() || part.equals(".")) continue;
        if (part.equals("..")) {
            if (!stack.isEmpty()) stack.remove(stack.size() - 1);
        } else {
            stack.add(part);
        }
    }
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) continue;
        if (part.equals("..")) {
            if (!stack.isEmpty()) stack.remove(stack.size() - 1);
        } else {
            stack.add(part);
        }
    }
    StringBuilder sb = new StringBuilder();
    if (leadingSlash) sb.append("/");
    for (int i = 0; i < stack.size(); i++) {
        if (i > 0) sb.append("/");
        sb.append(stack.get(i));
    }
    return sb.toString();
}

