            count++;
        }
    }
    if (count == array.length) {
        if (array instanceof String[]) {
            return (String[]) array;
        } else {
            String[] result = new String[count];
            for (int i = 0; i < array.length; i++) {
                result[i] = (String) array[i];
            }
            return result;
        }
    } else {
        String[] result = new String[count];
        int idx = 0;
        for (Object o : array) {
