public static String toString(final char ch) {
    // For ASCII 7-bit characters, use a cache to return the same String instance.
    // The cache is lazily initialized on first use.
    if (ch < 128) {
        // Use a static cache array defined in the enclosing class.
        // If the cache is not yet initialized, initialize it.
        if (toStringCache == null) {
            synchronized (String.class) {
                if (toStringCache == null) {
                    toStringCache = new String[128];
                    for (int i = 0; i < 128; i++) {
                        toStringCache[i] = new String(new char[]{(char) i});
                    }
                }
            }
        }
        return toStringCache[ch];
    }
    // Non-ASCII characters: create a new String each time.
    return String.valueOf(ch);
}

